import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"How do I let devices be discovered automatically and control which ones are listed?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/02.anleitungen/01.geraete-entdecken.md"},"headers":[],"relativePath":"adapter/esphome/anleitungen/geraete-entdecken.md","filePath":"adapter/esphome/anleitungen/geraete-entdecken.md","lastUpdated":null}'),d={name:"adapter/esphome/anleitungen/geraete-entdecken.md"};function s(i,e,n,c,h,l){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="how-do-i-let-devices-be-discovered-automatically-and-control-which-ones-are-listed" tabindex="-1">How do I let devices be discovered automatically and control which ones are listed? <a class="header-anchor" href="#how-do-i-let-devices-be-discovered-automatically-and-control-which-ones-are-listed" aria-label="Permalink to &quot;How do I let devices be discovered automatically and control which ones are listed?&quot;">​</a></h1><p><a id="auto-discovery-report-routers-foreign"></a></p><h2 id="why-does-auto-discovery-report-routers-or-foreign-devices-and-how-do-i-exclude-an-ip" tabindex="-1">Why does auto-discovery report routers or foreign devices and how do I exclude an IP? <a class="header-anchor" href="#why-does-auto-discovery-report-routers-or-foreign-devices-and-how-do-i-exclude-an-ip" aria-label="Permalink to &quot;Why does auto-discovery report routers or foreign devices and how do I exclude an IP?&quot;">​</a></h2><p>Discovery reports everything on the network that answers the search for ESPHome devices. Some routers and other devices answer as well and then appear in the tab &quot;Devices&quot; in the group &quot;Discovered, not added yet&quot;. The adapter never connects to discovered devices on its own, they stay there until you add them.</p><p>This excludes an address:</p><ol><li>Open the instance settings, tab &quot;Main settings&quot;, section &quot;Discovery&quot;.</li><li>Enter the address in the table &quot;IP addresses to be excluded by device discovery&quot;. Name and description are just for you.</li><li>Save. The instance restarts and skips the address from now on.</li></ol><p>The address must be written exactly as the device reports it. The list only affects discovery, a device you already added keeps connecting. If you do not need discovery at all, switch off &quot;Device discovery enabled&quot; and add devices by hand.</p><p><a id="choose-network-interface-device-discovery"></a></p><h2 id="can-i-choose-the-network-interface-for-device-discovery" tabindex="-1">Can I choose the network interface for device discovery? <a class="header-anchor" href="#can-i-choose-the-network-interface-for-device-discovery" aria-label="Permalink to &quot;Can I choose the network interface for device discovery?&quot;">​</a></h2><p>Yes. In the tab &quot;Main settings&quot;, section &quot;Discovery&quot;, &quot;Listening address&quot; sets the interface the adapter searches on. The field appears when &quot;Device discovery enabled&quot; is on.</p><table tabindex="0"><thead><tr><th>Entry</th><th>Effect</th></tr></thead><tbody><tr><td>empty or <code>0.0.0.0</code></td><td>searches on all IPv4 interfaces (default)</td></tr><tr><td>IPv4 address of the ioBroker host</td><td>searches on this interface only</td></tr><tr><td>IPv6 address of the ioBroker host</td><td>searches over IPv6 on this interface</td></tr></tbody></table><p>If the address belongs to no interface, the log shows a warning and the adapter searches on all IPv4 interfaces. The setting only applies to discovery. The adapter always connects to added devices by their address.</p><p><a id="devices-another-vlan-iobroker-runs"></a></p><h2 id="how-do-i-find-devices-in-another-vlan-or-when-iobroker-runs-in-docker" tabindex="-1">How do I find devices in another VLAN or when ioBroker runs in Docker? <a class="header-anchor" href="#how-do-i-find-devices-in-another-vlan-or-when-iobroker-runs-in-docker" aria-label="Permalink to &quot;How do I find devices in another VLAN or when ioBroker runs in Docker?&quot;">​</a></h2><p>Discovery uses mDNS, and mDNS only reaches the local network. It therefore does not find devices in another VLAN or behind a Docker network. Add such devices by hand with their IP address or host name, the connection itself works across networks.</p><p>For this the ioBroker host must reach the device on TCP port 6053, the port of the ESPHome API. Allow it in the firewall between the networks.</p><p>If ioBroker runs in Docker, the container only sees mDNS with the host network. Without the host network, add the devices by hand.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erstes-geraet#add-esphome-device-adapter">Add a device</a> · <a href="./../hintergrund/adapter-und-dashboard#adapter-dashboard-show-device-status">Device status in the dashboard</a></p><p><a id="adapter-support-iobroker-discovery"></a></p><h2 id="does-the-adapter-support-iobroker-discovery" tabindex="-1">Does the adapter support ioBroker.discovery? <a class="header-anchor" href="#does-the-adapter-support-iobroker-discovery" aria-label="Permalink to &quot;Does the adapter support ioBroker.discovery?&quot;">​</a></h2><p>Yes. ioBroker.discovery finds ESPHome devices on the network and suggests creating an instance of this adapter.</p><p>The adapter finds the devices themselves with its own discovery and does not need ioBroker.discovery for that. It runs while &quot;Device discovery enabled&quot; is on and shows discovered devices in the tab &quot;Devices&quot;.</p><p><strong>See also:</strong> <a href="#auto-discovery-report-routers-foreign">What discovery reports</a></p>',23)])])}const v=o(d,[["render",s]]);export{u as __pageData,v as default};
